'use strict';
async function gitPanel(){
 if(!window.amagoDesktop?.git){toast('A integração Git está disponível no aplicativo Windows.');return}
 modal('Repositório Git',`<p>Use a autenticação e a identidade já configuradas no Git do Windows.</p><div class="settings-button-grid"><button class="plain-button" id="git-clone">Clonar repositório</button><button class="plain-button" id="git-status">Atualizar estado</button></div><pre id="git-result" style="white-space:pre-wrap;max-height:240px;overflow:auto">Consultando…</pre><label>Mensagem do commit<input class="field" id="git-message" placeholder="Descreva as alterações"></label><label>Branch para mesclar<select class="field" id="git-branch"></select></label><div class="modal-actions"><button class="plain-button" data-git="fetch">Buscar atualizações</button><button class="plain-button" data-git="merge">Mesclar branch</button><button class="plain-button" data-git="resolve">Marcar conflitos editados como resolvidos</button><button class="plain-button" data-git="commit">Commit de todas as alterações</button><button class="solid-button" data-git="push">Enviar commits</button></div><p>O commit inclui todos os arquivos alterados e não ignorados do projeto. Mesclagens exigem uma árvore limpa. Não há envio forçado.</p>`);
 const show=result=>{const output=$('#git-result');if(!output)return;output.textContent=result.error||`Branch: ${result.branch||'(sem branch)'}\n\n${result.changes?.join('\n')||'Nenhuma alteração local.'}`;if(result.branches)$('#git-branch').innerHTML=result.branches.map(b=>`<option>${esc(b)}</option>`).join('')};
 const inspect=async()=>show(await window.amagoDesktop.git('status'));$('#git-status').onclick=inspect;
 $('#git-clone').onclick=()=>{modal('Clonar repositório',`<form id="git-clone-form"><label>URL HTTPS<input type="url" class="field" id="git-url" required placeholder="https://github.com/empresa/notas.git"></label><label>Nova pasta<input class="field" id="git-name" required value="notas"></label><p>A pasta será criada no local selecionado na próxima etapa.</p><button class="solid-button">Clonar e abrir</button><p id="clone-result" role="status"></p></form>`);$('#git-clone-form').onsubmit=async e=>{e.preventDefault();if(!(await saveProjectFile()))return;const button=e.target.querySelector('button');button.disabled=true;const result=await window.amagoDesktop.git('clone',{url:$('#git-url').value,name:$('#git-name').value});if(result.project){studio.files.clear();studio.panes=[];workbench.project=result.project;workbench.source='project';workbench.file=null;workbench.tabs=[];workbench.expanded=new Set();state.view='project';closeModal();render();indexProject(true)}else{button.disabled=false;$('#clone-result').textContent=result.error||'Operação cancelada.'}}};
 document.querySelectorAll('[data-git]').forEach(button=>button.onclick=async()=>{if(!(await saveProjectFile()))return;const op=button.dataset.git;if(['commit','push','merge'].includes(op)&&!confirm(op==='commit'?'Criar commit de todas as alterações listadas?':op==='push'?'Enviar os commits para o remoto configurado?':'Mesclar a branch selecionada? Conflitos serão preservados para resolução.'))return;document.querySelectorAll('[data-git]').forEach(b=>b.disabled=true);const result=await window.amagoDesktop.git(op,op==='commit'?$('#git-message').value:$('#git-branch').value);show(result);document.querySelectorAll('[data-git]').forEach(b=>b.disabled=false);if(op==='merge'){studio.files.clear();studio.panes=[];workbench.file=null;await refreshProject();renderMain()}});await inspect();
}
actions['git-project']=gitPanel;commandList.push(['Repositório Git','git-project','']);
$('.header-right').insertAdjacentHTML('beforeend','<button class="plain-button" data-action="git-project" title="Clonar e sincronizar repositórios">Git</button>');

function visualMarkdown(element){
 const inline=node=>{if(node.nodeType===3)return node.textContent.replace(/([*_`])/g,'\\$1');if(node.nodeType!==1)return '';const text=()=>[...node.childNodes].map(inline).join('');switch(node.tagName){case 'STRONG':case 'B':return '**'+text()+'**';case 'EM':case 'I':return '*'+text()+'*';case 'CODE':return '`'+node.textContent+'`';case 'BR':return '\n';case 'A':return '['+text()+']('+node.getAttribute('href')+')';case 'INPUT':return node.type==='checkbox'?(node.checked?'[x] ':'[ ] '):'';case 'BUTTON':return node.dataset.followReference?(node.dataset.referenceEmbed==='true'?'!':'')+'[['+node.dataset.followReference+'|'+node.textContent+']]':text();case 'H1':case 'H2':case 'H3':case 'H4':return '#'.repeat(+node.tagName[1])+' '+text()+'\n\n';case 'P':case 'DIV':return text()+'\n\n';case 'BLOCKQUOTE':return text().trim().split('\n').map(l=>'> '+l).join('\n')+'\n\n';case 'LI':return '- '+text().trim()+'\n';case 'OL':return [...node.children].map((li,i)=>(i+1)+'. '+[...li.childNodes].map(inline).join('').trim()).join('\n')+'\n\n';case 'UL':return text()+'\n';case 'PRE':return '```\n'+node.textContent.replace(/\n$/,'')+'\n```\n\n';default:return text()}};
 return [...element.childNodes].map(inline).join('').trimEnd();
}
function mountVisualEditors(){for(const preview of document.querySelectorAll('#preview,#project-preview,.pane-preview')){
 if(preview.dataset.visualReady)continue;const pane=preview.closest('[data-pane]'),ref=pane?studio.panes[+pane.dataset.pane]:null,doc=ref?paneDocument(ref):preview.id==='project-preview'?workbench.file:note(),project=ref?ref.source==='project':preview.id==='project-preview';if(!doc||doc.kind==='text')continue;preview.dataset.visualReady='true';
 const front=doc.body.match(/^---\r?\n[\s\S]*?\r?\n---(?:\r?\n|$)/)?.[0]||'',body=doc.body.slice(front.length),chunks=body.split(/(\n\s*\n)/),records=[];let fenced=false,raw='';const blocks=[];for(const line of body.split('\n')){if(/^\s*(?:```|~~~)/.test(line))fenced=!fenced;if(!fenced&&!line.trim()&&raw){blocks.push(raw);raw=''}else raw+=(raw?'\n':'')+line}if(raw)blocks.push(raw);
 preview.innerHTML='';const toolbar=document.createElement('div');toolbar.className='visual-toolbar';toolbar.innerHTML='<span>Edição visual</span><button type="button" data-format="bold"><b>B</b></button><button type="button" data-format="italic"><i>I</i></button><button type="button" data-format="undo">Desfazer</button>';preview.before(toolbar);toolbar.onmousedown=e=>{const button=e.target.closest('[data-format]');if(button){e.preventDefault();document.execCommand(button.dataset.format)}};
 for(const source of blocks.length?blocks:['']){const block=document.createElement('div');block.className='visual-block';block.contentEditable='true';block.setAttribute('role','textbox');block.setAttribute('aria-label','Editar trecho do documento');block.innerHTML=(project?fileMarkdown(source,doc):markdown(source,false,doc))||'<p><br></p>';const initial=block.innerHTML;records.push({block,source,initial});preview.append(block)}
 preview.addEventListener('paste',e=>{if(!e.target.closest('.visual-block'))return;e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'))});
 preview.oninput=()=>{doc.body=front+records.map(r=>r.block.innerHTML===r.initial?r.source:visualMarkdown(r.block)).join('\n\n');if(project){doc.dirty=doc.body!==doc.savedBody;markFileStatus('Alterações não salvas');if(ref)studio.files.set(doc.path,doc)}else{doc.updated=stamp();persist()}const editor=preview.parentElement.querySelector('textarea');if(editor)editor.value=doc.body;};
 }}
const visualRenderMain=renderMain;renderMain=function(){visualRenderMain();mountVisualEditors()};
document.addEventListener('input',e=>{if(e.target.matches('#editor,#project-editor')){const preview=e.target.parentElement.querySelector('.markdown');if(preview){preview.removeAttribute('data-visual-ready');preview.previousElementSibling?.classList.contains('visual-toolbar')&&preview.previousElementSibling.remove();mountVisualEditors()}}});
mountVisualEditors();
